import{_ as t,c as a,a0 as o,o as s}from"./chunks/framework.BGabeMLJ.js";const p=JSON.parse('{"title":"Security & Operations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/node-security.md","filePath":"guide/deployment/node-security.md"}'),r={name:"guide/deployment/node-security.md"};function i(n,e,d,l,h,c){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="security-operations" tabindex="-1">Security &amp; Operations <a class="header-anchor" href="#security-operations" aria-label="Permalink to &quot;Security &amp; Operations&quot;">​</a></h1><p>This page is a technical reference for IT security officers, data protection officers and operators who assess or run a FLAME Node. It describes how the Node behaves today (Helm chart <code>flame-node</code> 1.0.x) and is intended to be referenced from site-specific documents such as an operating concept (Betriebskonzept), data protection concept or information security concept.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><h3 id="inbound" tabindex="-1">Inbound <a class="header-anchor" href="#inbound" aria-label="Permalink to &quot;Inbound&quot;">​</a></h3><p>The Hub never opens a connection to a Node. All communication between Node and Hub is <strong>initiated by the Node</strong> (outbound HTTPS and a WebSocket connection to the Hub messenger). Nodes do not talk to each other directly; messages and intermediate results are relayed through the Hub.</p><p>The Node therefore does <strong>not</strong> need to be reachable from the internet. Inbound access is only needed so that local staff (node administrators, data stewards) can open the Node UI in their browser. Whether this is reachable from the clinic network only, via VPN, or from outside is a site decision. By default the chart exposes nothing (<code>expose.type: none</code>).</p><p>When <code>expose.type</code> is <code>ingress</code> or <code>gateway</code>, the chart creates routes on a single hostname:</p><table tabindex="0"><thead><tr><th>Path</th><th>Target</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/</code></td><td>Node UI (3000)</td><td>Web interface</td></tr><tr><td><code>/api</code></td><td>Hub Adapter (5000)</td><td>Backend called by the Node UI in the browser</td></tr><tr><td><code>/keycloak/</code></td><td>Keycloak (80)</td><td>Node-internal service authentication</td></tr><tr><td><code>/logs</code> (optional, off)</td><td>VictoriaLogs (9428)</td><td>Log UI – <strong>no authentication</strong>, do not expose publicly</td></tr></tbody></table><p>Researchers never interact with the Node. They work exclusively with the Hub.</p><div class="tip custom-block"><p class="custom-block-title">Browser access to the Hub</p><p>The Node UI logs users in via the Hub. The browsers of node staff must therefore be able to reach the Hub auth endpoint as well.</p></div><h3 id="outbound" tabindex="-1">Outbound <a class="header-anchor" href="#outbound" aria-label="Permalink to &quot;Outbound&quot;">​</a></h3><p>All outbound connections use HTTPS (TCP 443) unless you configure different endpoints.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Used by</th><th>Purpose</th></tr></thead><tbody><tr><td><code>hub.endpoints.core</code></td><td>Pod Orchestrator, Hub Adapter, Storage, Broker</td><td>Hub API (projects, analyses, status, logs)</td></tr><tr><td><code>hub.endpoints.auth</code></td><td>all node services, user browsers</td><td>Token issuing (client credentials, user login)</td></tr><tr><td><code>hub.endpoints.messenger</code></td><td>Message Broker</td><td>Socket.io / WebSocket for node-to-node messages</td></tr><tr><td><code>hub.endpoints.storage</code></td><td>Storage Service</td><td>Upload of intermediate and final results</td></tr><tr><td>Harbor registry of the Hub</td><td>container runtime (kubelet)</td><td>Pulling analysis images</td></tr><tr><td><code>ghcr.io</code>, <code>docker.io</code>, <code>quay.io</code></td><td>container runtime (kubelet)</td><td>Pulling the Node&#39;s own component images</td></tr></tbody></table><p>The Hub endpoints are configured under <code>hub.endpoints</code> in the values file. The Harbor host is the registry selected for your node in the Hub.</p><div class="warning custom-block"><p class="custom-block-title">Proxies</p><p>The <code>proxy.*</code> values only apply to the Node services. Image pulls (analysis images from Harbor and component images) are performed by the container runtime of your Kubernetes nodes. If outbound traffic has to pass a proxy, configure it for the container runtime (e.g. containerd) as well.</p></div><h3 id="isolation-of-analyses" tabindex="-1">Isolation of analyses <a class="header-anchor" href="#isolation-of-analyses" aria-label="Permalink to &quot;Isolation of analyses&quot;">​</a></h3><p>Every analysis runs in its own pod. The Pod Orchestrator creates a dedicated nginx proxy and a <code>NetworkPolicy</code> per analysis that only allows traffic between the analysis pod and its proxy (plus DNS lookups to the cluster DNS). The proxy in turn only forwards an allow-list of requests: data access through Kong for the project&#39;s data stores, the storage service (results), the message broker (for this analysis only) and log streaming. Analysis containers therefore have <strong>no internet access</strong> and no access to other Node services.</p><p>This requires a CNI plugin that enforces network policies (e.g. Calico), see <a href="./node-installation.html#kubernetes">Requirements</a>. The chart does not ship a namespace-wide default-deny policy; sites may add one.</p><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Protection</th></tr></thead><tbody><tr><td>Node → Hub (API, auth, storage, messenger)</td><td>TLS, server certificate verified (system trust store + optional <a href="./node-installation.html#additional-certificate-authority-ca-certificates">custom CAs</a>)</td></tr><tr><td>Browser → Node UI</td><td>TLS terminated at your ingress / reverse proxy</td></tr><tr><td>Messages between nodes (via Hub messenger)</td><td>TLS <strong>and</strong> end-to-end: ECDH (P-256) key agreement + AES-256-GCM</td></tr><tr><td>Intermediate results between nodes (via Hub storage)</td><td>TLS <strong>and</strong> end-to-end: ECDH (P-256) + HKDF-SHA256 + AES-GCM</td></tr><tr><td>Final results (Node/Aggregator → Hub)</td><td>TLS only. Final results are aggregated, not end-to-end encrypted, and stored in the Hub result storage</td></tr><tr><td>Kong → data stores (FHIR, S3)</td><td>Configurable per data store (HTTP or HTTPS, optional client certificate / CA)</td></tr><tr><td>Communication inside the cluster</td><td>Plain HTTP between Node services; no service mesh / mTLS</td></tr></tbody></table><p>Encryption inside the cluster can be added by the site (e.g. through a service mesh) if required by local policy.</p><h3 id="node-key-pair" tabindex="-1">Node key pair <a class="header-anchor" href="#node-key-pair" aria-label="Permalink to &quot;Node key pair&quot;">​</a></h3><p>Each node has an ECDH key pair (curve P-256) used for the end-to-end encryption above.</p><ul><li>The key pair is generated <strong>in the administrator&#39;s browser</strong> via the WebCrypto API when clicking &quot;Generate&quot; in the Hub UI (<a href="./node-registration.html#crypto">Registering in the Hub</a>).</li><li>Only the <strong>public key</strong> is sent to and stored by the Hub. The private key is shown once for copying and is not stored anywhere by the Hub.</li><li>The private key is provided to the Node at deployment (<code>hub.crypto.privateKey</code> or <code>hub.crypto.existingSecret</code>) and stored as a Kubernetes Secret. It is mounted only into the storage service and the message broker.</li><li>To rotate the key, generate a new pair in the Hub, save it, and update the Secret on the Node.</li></ul><p>The key generation code is part of the open-source Hub UI and is delivered by the Hub operator over TLS. Trust in its integrity is therefore trust in the Hub operator. FLAME does not currently publish SBOMs or signatures for its container images.</p><h2 id="integrity-of-analysis-code" tabindex="-1">Integrity of analysis code <a class="header-anchor" href="#integrity-of-analysis-code" aria-label="Permalink to &quot;Integrity of analysis code&quot;">​</a></h2><ol><li>A researcher uploads the analysis code to the Hub and selects a master image.</li><li>Every participating node&#39;s administrator can <strong>download and review the code</strong> and must <strong>approve</strong> it before the image is built (<a href="./../admin/analysis-review.html">Analysis Review</a>).</li><li>After all nodes have decided, the Hub builds a container image from the master image and the approved code. The Hub does <strong>not</strong> sign this image. Instead it records the image&#39;s content hash (<code>sha256</code> image ID), which is shown in the Hub UI in the analysis&#39; build step.</li><li>The image is pushed to a <strong>private project per node</strong> in the Hub&#39;s Harbor registry. Each node pulls only from its own project using node-specific robot credentials.</li><li>Administrators can compare the hash shown in the Hub with the image present on their node, e.g. <code>crictl inspecti &lt;image&gt;</code> (field <code>id</code>) or <code>microk8s ctr images ls</code>.</li></ol><h3 id="master-images" tabindex="-1">Master images <a class="header-anchor" href="#master-images" aria-label="Permalink to &quot;Master images&quot;">​</a></h3><p>Master images contain the base runtime and libraries for analyses. They are maintained in the public <a href="https://github.com/PrivateAIM/master-images" target="_blank" rel="noreferrer">master-images</a> repository and built by the Hub.</p><ul><li>Changes require a reviewed pull request; only maintainers can merge into the release branch.</li><li>Images are scanned for known vulnerabilities (CVE) in CI before release.</li><li>Only Hub users with the <code>MASTER_IMAGE_MANAGE</code> permission can trigger synchronisation and building of master images in the Hub.</li></ul><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to &quot;Access control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Where</th><th>Who</th></tr></thead><tbody><tr><td>User accounts, identity providers, realms</td><td>Hub</td><td>Hub operator / realm administrators</td></tr><tr><td>Creating projects and analyses</td><td>Hub</td><td>Researchers</td></tr><tr><td>Participation of a node in a project</td><td>Hub (or Node UI)</td><td>Node administrator of the site</td></tr><tr><td>Approval of an analysis (after code review)</td><td>Hub (or Node UI)</td><td>Node administrator of the site</td></tr><tr><td>Starting / stopping analyses on the node</td><td>Node UI</td><td>Node roles <code>admin</code>, <code>researcher</code></td></tr><tr><td>Configuring data stores (which data an analysis can access)</td><td>Node UI</td><td>Node roles <code>admin</code>, <code>steward</code></td></tr><tr><td>Data access of an analysis</td><td>Node (Kong)</td><td>Enforced per project: an analysis can only reach the data stores of its own project</td></tr></tbody></table><p>Node UI users log in with their Hub account. Node roles (<code>admin</code>, <code>steward</code>, <code>researcher</code>) are read from the <code>global_access.roles</code> claim of the Hub token, i.e. they are <strong>global roles on the Hub</strong> and are assigned by the Hub operator (see <a href="./node-installation.html#role-based-access-control-rbac">Role-Based Access Control</a>). Technical staff with access to the Kubernetes cluster (e.g. <code>kubectl</code>) have further access paths in the context of their work, e.g. to secrets and databases of the Node; these are governed by the site&#39;s own operating rules.</p><h3 id="identity-of-researchers" tabindex="-1">Identity of researchers <a class="header-anchor" href="#identity-of-researchers" aria-label="Permalink to &quot;Identity of researchers&quot;">​</a></h3><p>Researchers authenticate at the Hub, not at the site. Accounts are created or approved by the Hub operator, or federated from an identity provider such as the researcher&#39;s home institution. The home institution is accountable for its researchers under the respective data usage agreement. Independently of this, each site decides via project and analysis approval whether its data is used.</p><h2 id="results-and-disclosure-control" tabindex="-1">Results and disclosure control <a class="header-anchor" href="#results-and-disclosure-control" aria-label="Permalink to &quot;Results and disclosure control&quot;">​</a></h2><p>Only results that an analysis explicitly submits leave a node. Raw data never leaves the node.</p><ul><li><strong>Code review:</strong> Before an analysis can run, the node administrator reviews the code and verifies that only aggregated results are returned in accordance with the study protocol. This is the primary safeguard.</li><li><strong>Network isolation:</strong> Analyses cannot send data anywhere except through the storage service and message broker (see <a href="#isolation-of-analyses">Isolation of analyses</a>).</li><li><strong>Local differential privacy (optional):</strong> The SDK can add Laplace noise to a numeric final result on the node (<code>submit_final_result(..., local_dp=...)</code>). Epsilon and sensitivity are chosen by the analysis and should be checked during the review.</li><li><strong>Logs:</strong> Analysis logs are visible to the node administrators and, by default, forwarded to the Hub (<code>enableHubLogging</code>). Review analysis code for logging of sensitive values.</li></ul><div class="warning custom-block"><p class="custom-block-title">No automatic anonymity checks</p><p>FLAME does not automatically enforce minimum cohort sizes, k-anonymity thresholds or other output checks. Aggregation alone does not guarantee anonymity; the adequacy of the returned results must be assessed during the review of each analysis.</p></div><h2 id="logging-and-audit" tabindex="-1">Logging and audit <a class="header-anchor" href="#logging-and-audit" aria-label="Permalink to &quot;Logging and audit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What</th><th>Retention</th></tr></thead><tbody><tr><td>Node</td><td>JSON logs of all node services and analyses, collected into VictoriaLogs</td><td>1 year (<code>victorialogs</code> values)</td></tr><tr><td>Node</td><td>User actions in the Node UI (Hub Adapter events, including user name), stored in PostgreSQL and the logs</td><td>as above</td></tr><tr><td>Node</td><td>Analysis logs and network statistics per analysis, stored with the analysis in PostgreSQL</td><td>until the analysis is deleted</td></tr><tr><td>Hub</td><td>Events on Hub resources (create/update/delete of projects, analyses, approvals, …) with actor</td><td>1 year (planned; currently <code>EVENT_RETENTION_DAYS</code>, default 7 days)</td></tr></tbody></table><p>Logs are stored in regular databases and are <strong>not</strong> tamper-evident (no hash chain or WORM storage). If a tamper-evident audit trail is required, forward the logs to the site&#39;s SIEM or WORM storage.</p><h2 id="state-backup-and-recovery" tabindex="-1">State, backup and recovery <a class="header-anchor" href="#state-backup-and-recovery" aria-label="Permalink to &quot;State, backup and recovery&quot;">​</a></h2><h3 id="stateful-components" tabindex="-1">Stateful components <a class="header-anchor" href="#stateful-components" aria-label="Permalink to &quot;Stateful components&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Volume (default)</th><th>Contents</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>8 GiB</td><td>Analyses and their status/logs, Hub Adapter events and settings</td></tr><tr><td>Kong PostgreSQL</td><td>2 GiB</td><td>Data store configuration (services, routes, consumers)</td></tr><tr><td>Keycloak PostgreSQL</td><td>8 GiB</td><td>Node-internal service clients</td></tr><tr><td>SeaweedFS</td><td>10 GiB</td><td>Local results and checkpoints of analyses</td></tr><tr><td>MongoDB</td><td>500 MiB</td><td>Message broker state</td></tr><tr><td>VictoriaLogs</td><td>20 GiB</td><td>Logs</td></tr></tbody></table><p>Research data itself is <strong>not</strong> stored by the Node unless you enable the optional data store subchart; it remains in your data sources (FHIR server, S3) and is backed up there.</p><h3 id="what-to-back-up" tabindex="-1">What to back up <a class="header-anchor" href="#what-to-back-up" aria-label="Permalink to &quot;What to back up&quot;">​</a></h3><ul><li>The PostgreSQL volumes (at least the main and Kong databases) and optionally SeaweedFS and VictoriaLogs.</li><li>The Kubernetes Secrets of the release, in particular <code>&lt;release&gt;-ecdh-private-key-secret</code> (the Hub does not store the private key) and <code>&lt;release&gt;-hub-client-secret</code>, as well as the generated database credentials.</li><li>Your values file.</li></ul><h3 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h3><p>All components run with one replica. High availability (multiple replicas, leader election, hot failover) is <strong>not supported</strong>. Recovery relies on Kubernetes: crashed pods are restarted automatically, and running analyses keep running while the Pod Orchestrator restarts. The Pod Orchestrator resumes from its database and restarts stuck analyses up to three times. If a restart does not help, restore the last backup or redeploy the release with the backed-up values and secrets.</p><h2 id="releases-and-updates" tabindex="-1">Releases and updates <a class="header-anchor" href="#releases-and-updates" aria-label="Permalink to &quot;Releases and updates&quot;">​</a></h2><ul><li><p>All components follow <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a> and are released with release-please. Each release has a changelog; breaking changes are listed under <strong>⚠ BREAKING CHANGES</strong>.</p><ul><li>Node Helm chart: <a href="https://github.com/PrivateAIM/helm/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">PrivateAIM/helm CHANGELOG</a>, notable upgrade steps are described in the <a href="/versions/v0.1.0.html">version notes</a> of this documentation.</li><li>Hub: <a href="https://github.com/PrivateAIM/hub/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">PrivateAIM/hub CHANGELOG</a></li></ul></li><li><p>The Node chart is published in the Helm repository <code>https://PrivateAIM.github.io/helm</code>. Update a node with</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --namespace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NAMESPAC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flame-node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flame/flame-node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">VERSIO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Read the changelog before upgrading across a breaking change.</p></li><li><p>A <strong>software update</strong> in this sense is a patch or minor release (bug fixes, security fixes, dependency updates). A <strong>release change</strong> is a new major release that may require changes to the configuration.</p></li><li><p>A policy for stable, long-term supported releases and maintenance windows will be published before the end of the project.</p></li></ul>`,52)]))}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
